esult\\\": \\\"FRESH_TRUE159_FULL_NATIVE_RESTORE_DATA_SCHEMA_ACL_SEQUENCES_AND_ROLES_EQUAL\\\",\\n  \\\"risks\\\": [\\n    \\\"Continuous formal zero-execution migration window and signed bundle schema compatibility remain separate\\\",\\n    \\\"No actual migration/formal identity/current install/eight pages/business first chain\\\"\\n  ],\\n  \\\"schema\\\": \\\"aos-memory-delivery-receipt/v1\\\",\\n  \\\"task_id\\\": \\\"qyh-current159-fresh-backup-restore-20261012\\\",\\n  \\\"verification\\\": [\\n    \\\"New isolated network-none owned DB native single-transaction restore exit0; earlier empty rollback retained\\\",\\n    \\\"All647 table row counts/SHA equal and true source unchanged\\\",\\n    \\\"Complete native schema-only owner/ACL SQL byte-equal after only pg_dump random restriction token removal\\\",\\n    \\\"12 sequence value/called equal;39 role flags/config and12 member grantors/options equal\\\"\\n  ]\\n}\\n\", \".evidence/qyh-current159-named-lab-retention-20261013/material-8.txt\": \"{\\n  \\\"containerId\\\": \\\"3fb59cb46c8daeb402caee95bf9f2d9aefbb3aa42d87988811afe29418790687\\\",\\n  \\\"volume\\\": \\\"aos-qyh-current159-exact-restore-20261012\\\"\\n}\", \".evidence/qyh-current159-named-lab-retention-20261013/material-9.txt\": \"{\\n  \\\"containerId\\\": \\\"951749982fad112b99e59e028c60ec126024c3ea3b1ed6288a2d14cb2d644de2\\\",\\n  \\\"volume\\\": \\\"aos-qyh-current159-restore-lab-20261012\\\"\\n}\", \".evidence/qyh-current159-named-lab-retention-20261013/material-10.txt\": \"\\\"\\\"\\\"Preserve the completed owned lab's volume and archives; stop its exact CID.\\\"\\\"\\\"\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport shutil\\nimport subprocess\\n\\nOUT = Path(__file__).resolve().parent\\nCONTEXT = 'colima-aos-extension'\\nCID = '52cc28f30197cc4010bd0167139e849e239591d7d9c47023ebcb36ac06164e7c'\\nVOLUME = 'aos-qyh-source161-clean-maintenance-data-20261012'\\nOWNER = 'codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2'\\nRECEIPTS = OUT.parents[2]/'docs/palantier/AOS项目开发上下文/memory/receipts'\\n\\n\\ndef record(name, value):\\n    with (OUT/name).open('x') as file:\\n        json.dump(value,file,ensure_ascii=False,indent=2)\\n\\n\\ndef docker(*args, **kwargs):\\n    return subprocess.run(['docker','--context',CONTEXT,*args],\\n                          check=True,timeout=60,**kwargs)\\n\\n\\ndef catalog():\\n    query = \\\"\\\"\\\"BEGIN READ ONLY; SELECT json_build_object(\\n        'cluster',(SELECT system_identifier::text FROM pg_control_system()),\\n        'databases',(SELECT json_agg(datname ORDER BY datname) FROM pg_database WHERE NOT datistemplate),\\n        'otherClients',(SELECT count(*) FROM pg_stat_activity WHERE pid<>pg_backend_pid()\\n            AND backend_type='client backend')); COMMIT;\\\"\\\"\\\"\\n    return json.loads(docker('exec','-i',CID,'psql','-X','-qAt','-v','ON_ERROR_STOP=1',\\n        '-U','aos_app','-d','postgres',input=query,text=True,capture_output=True).stdout)\\n\\n\\nif __name__ == '__main__':\\n    task = json.loads((RECEIPTS/'tasks/qyh-source161-clean-maintenance-lab-20261012.json').read_text())\\n    delivery = json.loads((RECEIPTS/'deliveries/qyh-source161-clean-maintenance-lab-20261012.json').read_text())\\n    assert task['owner']==OWNER and delivery['task_id']==task['task_id']\\n    assert delivery['completed_at'] and 'aos-platform/maintenance/qiyuehui-source161-clean-maintenance-lab' in task['scope']\\n    original = json.loads(docker('inspect',CID,capture_output=True,text=True).stdout)[0]\\n    assert original['Id']==CID and original['State']['Running']\\n    assert original['Name']=='/qyh-source161-clean-maintenance-lab-20261012'\\n    assert original['HostConfig']['NetworkMode']=='none' and not original['HostConfig']['PortBindings']\\n    assert len(original['Mounts'])==1 and original['Mounts'][0]['Name']==VOLUME\\n    assert original['Mounts'][0]['Type']=='volume'\\n    before = catalog()\\n    assert before['cluster']=='7695744911813242913' and before['otherClients']==0\\n    assert all(re.fullmatch('[a-zA-Z0-9_]+',name) for name in before['databases'])\\n    record('intent.json',{'owner':OWNER,'completedOriginalTask':task['task_id'],\\n        'container':CID,'volume':VOLUME,'catalog':before,'sourceDatabaseAffected':False})\\n    private = OUT/'private'\\n    private.mkdir(mode=0o700)\\n    archive_hashes = {}\\n    commands = [(name+'.dump',['pg_dump','-U','aos_app','-d',name,'-Fc'])\\n                for name in before['databases']]\\n    commands.append(('globals.sql',['pg_dumpall','-U','aos_app','--globals-only','--no-role-passwords']))\\n    for filename,command in commands:\\n        path = private/filename\\n        fd = os.open(path,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)\\n        with os.fdopen(fd,'wb') as file:\\n            docker('exec',CID,*command,stdout=file,stderr=subprocess.PIPE)\\n        second = private/(filename+'.second')\\n        shutil.copyfile(path,second)\\n        second.chmod(0o600)\\n        digest = hashlib.sha256(path.read_bytes()).hexdigest()\\n        assert hashlib.sha256(second.read_bytes()).hexdigest()==digest\\n        archive_hashes[filename]=digest\\n        if filename.endswith('.dump'):\\n            docker('exec','-i',CID,'pg_restore','--list',input=path.read_bytes(),\\n                   stdout=subprocess.PIPE,stderr=subprocess.PIPE)\\n    assert catalog()==before\\n    record('backup-terminal.json',{'completeDatabaseArchives':len(before['databases']),\\n        'secondCopiesEqual':True,'archiveListReadable':True,'catalogUnchanged':True,\\n        'files':archive_hashes,'volumeRetained':True})\\n    record('stop-intent.json',{'container':CID,'volume':VOLUME,'removeVolume':False,\\n        'completedOwner':OWNER,'activeClients':0})\\n    docker('stop','--time','10',CID,capture_output=True,text=True)\\n    stopped = json.loads(docker('inspect',CID,capture_output=True,text=True).stdout)[0]\\n    retained = json.loads(docker('volume','inspect',VOLUME,capture_output=True,text=True).stdout)[0]\\n    assert not stopped['State']['Running'] and stopped['Id']==CID\\n    assert retained['Name']==VOLUME and stopped['Mounts'][0]['Name']==VOLUME\\n    for name,digest in archive_hashes.items():\\n        assert hashlib.sha256((private/name).read_bytes()).hexdigest()==digest\\n        assert hashlib.sha256((private/(name+'.second')).read_bytes()).hexdigest()==digest\\n    memory = docker('exec','qyh-restored-pg-20261011','cat','/proc/meminfo',\\n                    capture_output=True,text=True).stdout\\n    available = int(next(line for line in memory.splitlines() if line.startswith('MemAvailable:')).split()[1])\\n    record('verification.json',{'outcome':'COMPLETED_OWNED_NAMED_LAB_STOPPED_DATA_RETAINED',\\n        'container':CID,'volume':VOLUME,'volumeStillExists':True,'allBackupHashesValid':True,\\n        'databaseArchives':len(before['databases']),'measuredVmAvailableKB':available,\\n        'otherContainersStopped':False,'currentServicesRestarted':False,\\n        'fullRestoreRehearsalPassed':False,'goalUpdated':False})\\n    print('COMPLETED_OWNED_NAMED_LAB_STOPPED_DATA_RETAINED',available)\\n\"}}"}],"timestamp":1791844994547}}
{"type":"message_end","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-current159-named-lab-retention-20261013-r2\", \"task_id\": \"qyh-current159-named-lab-retention-20261013\", \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\", \"kind\": \"quality\", \"baseline\": {\"head\": \"e3bb1ed1d69521307d6aa2ba48bd7e5972703131\", \"authority_revision\": \"AOS-001996\", \"files\": {\".evidence/qyh-current159-named-lab-retention-20261013/material-0.txt\": \"d348c0d440e6f3e090aaef7c582a1809f74e813ce95e811efe1705814e41a8ad\", \".evidence/qyh-current159-named-lab-retention-20261013/material-1.txt\": \"9cf049627cb78677dc281863d8743c77f70240d4b88306d33dd3fff5bcff58e6\", \".evidence/qyh-current159-named-lab-retention-20261013/material-2.txt\": \"f5d62818053b04f0db9a923fb80b8e6fcb29f94e7384331daeaed32a0e79a592\", \".evidence/qyh-current159-named-lab-retention-20261013/material-3.txt\": \"927c2a3db19da552a50c7e21d822f53ef4507c02f1941ba3d4ca7678cebc1f60\", \".evidence/qyh-current159-named-lab-retention-20261013/material-4.txt\": \"9ec830011187714cfa5b4668fbe1ea19b94609045326b9038bd111fb4fa2b758\", \".evidence/qyh-current159-named-lab-retention-20261013/material-5.txt\": \"177a80f0af7529b742fa73808d5c6e6ee671c116c646695600bf7a059400de5a\", \".evidence/qyh-current159-named-lab-retention-20261013/material-6.txt\": \"c558b75c53265c2cfe4afcdd5447d950f930e381b974edd0745afc3612b8f109\", \".evidence/qyh-current159-named-lab-retention-20261013/material-7.txt\": \"261e64fcdb0de19e98453f50a7f9222e1c26090ecc502920bbab8fb7c460abf9\", \".evidence/qyh-current159-named-lab-retention-20261013/material-8.txt\": \"70e1f2605ca2d6818f08b4d6e3df0493b5526c7d54ec87dc29a7ee0e6671ce75\", \".evidence/qyh-current159-named-lab-retention-20261013/material-9.txt\": \"433fbb1f5957ad81062bd46044149f5918a855cfebd9f2e850241d9d327d8043\", \".evidence/qyh-current159-named-lab-retention-20261013/material-10.txt\": \"a018ba1edb6cea0780475a4e8dfd8b4c2f45d60294ec757358268ed1981c421d\"}}, \"claims\": [\"The workflow reconciles the exact historical owner and completed Task, creation evidence, named volumes and absence of clients before new stop intents.\", \"The two retained lab databases receive complete native archives and second-copy hashes, and their original named volumes remain after stopping exact owned containers.\", \"The failed historical lab is retained without presenting it or released memory as a successful full restore or runtime activation.\"], \"materials\": {\".evidence/qyh-current159-named-lab-retention-20261013/material-0.txt\": \"\\\"\\\"\\\"Archive two exact historical named labs; keep volumes, source and failed data.\\\"\\\"\\\"\\nimport hashlib\\nimport importlib.util\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport shutil\\nimport subprocess\\n\\nOUT=Path(__file__).resolve().parent\\nROOT=OUT.parents[1]\\nOLD=ROOT/'.evidence/qyh-current159-fresh-backup-restore-20261012'\\nspec=importlib.util.spec_from_file_location('retention_helpers',ROOT /\\n    '.evidence/qyh-completed-named-lab-resource-retention-20261013/retain.py')\\nR=importlib.util.module_from_spec(spec)\\nspec.loader.exec_module(R)\\nLABS=[('exact','qyh-current159-exact-restore-20261012','exact-lab-created.json'),\\n      ('failed-retained','qyh-current159-restore-lab-20261012','lab-created.json')]\\n\\n\\nif __name__=='__main__':\\n    task=json.loads((R.RECEIPTS/'tasks/qyh-current159-fresh-backup-restore-20261012.json').read_text())\\n    delivery=json.loads((R.RECEIPTS/'deliveries/qyh-current159-fresh-backup-restore-20261012.json').read_text())\\n    assert task['owner']=='codex-thread-01a107a2-e9e4-7670-bc44-1144fa9b27e2'\\n    assert delivery['task_id']==task['task_id'] and delivery['completed_at']\\n    assert 'aos-platform/maintenance/qyh-current159-owned-restore' in task['scope']\\n    results=[]\\n    for label,name,proof in LABS:\\n        original=json.loads((OLD/proof).read_text())\\n        R.CID=original['containerId'];R.VOLUME=original['volume'];R.OUT=OUT/label\\n        R.OUT.mkdir()\\n        native=json.loads(R.docker('inspect',R.CID,capture_output=True,text=True).stdout)[0]\\n        assert native['Id']==R.CID and native['Name']=='/'+name and native['State']['Running']\\n        assert native['HostConfig']['NetworkMode']=='none' and not native['HostConfig']['PortBindings']\\n        assert len(native['Mounts'])==1 and native['Mounts'][0]['Type']=='volume'\\n        assert native['Mounts'][0]['Name']==R.VOLUME\\n        before=R.catalog()\\n        assert before['otherClients']==0 and before['cluster']\\n        assert all(re.fullmatch('[a-zA-Z0-9_]+',db) for db in before['databases'])\\n        R.record('intent.json',{'originalOwner':task['owner'],'originalTask':task['task_id'],\\n            'container':R.CID,'volume':R.VOLUME,'catalog':before,'failedOriginalLab':label=='failed-retained'})\\n        private=R.OUT/'private';private.mkdir(mode=0o700)\\n        commands=[(db+'.dump',['pg_dump','-U','aos_app','-d',db,'-Fc']) for db in before['databases']]\\n        commands.append(('globals.sql',['pg_dumpall','-U','aos_app','--globals-only','--no-role-passwords']))\\n        checks={}\\n        for filename,args in commands:\\n            p=private/filename\\n            with os.fdopen(os.open(p,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600),'wb') as f:\\n                R.docker('exec',R.CID,*args,stdout=f,stderr=subprocess.PIPE)\\n            second=private/(filename+'.second');shutil.copyfile(p,second);second.chmod(0o600)\\n            digest=hashlib.sha256(p.read_bytes()).hexdigest()\\n            assert hashlib.sha256(second.read_bytes()).hexdigest()==digest\\n            checks[filename]=digest\\n            if filename.endswith('.dump'):\\n                R.docker('exec','-i',R.CID,'pg_restore','--list',input=p.read_bytes(),\\n                         stdout=subprocess.PIPE,stderr=subprocess.PIPE)\\n        assert R.catalog()==before\\n        R.record('backup-terminal.json',{'archiveCount':len(before['databases']),\\n            'files':checks,'secondCopiesEqual':True,'archiveListsReadable':True,'catalogUnchanged':True})\\n        R.record('stop-intent.json',{'container':R.CID,'volume':R.VOLUME,'removeVolume':False})\\n        R.docker('stop','--time','10',R.CID,capture_output=True,text=True)\\n        stopped=json.loads(R.docker('inspect',R.CID,capture_output=True,text=True).stdout)[0]\\n        volume=json.loads(R.docker('volume','inspect',R.VOLUME,capture_output=True,text=True).stdout)[0]\\n        assert not stopped['State']['Running'] and volume['Name']==R.VOLUME\\n        for filename,digest in checks.items():\\n            assert hashlib.sha256((private/filename).read_bytes()).hexdigest()==digest\\n            assert hashlib.sha256((private/(filename+'.second')).read_bytes()).hexdigest()==digest\\n        result={'container':R.CID,'originalVolumeRetained':R.VOLUME,'stopped':True,\\n            'completeArchives':len(before['databases']),'backupHashesValid':True,\\n            'failedLabPreservedNotAccepted':label=='failed-retained'}\\n        R.record('verification.json',result);results.append(result)\\n    R.OUT=OUT\\n    memory=R.docker('exec','qyh-restored-pg-20261011','cat','/proc/meminfo',capture_output=True,text=True).stdout\\n    available=int(next(x for x in memory.splitlines() if x.startswith('MemAvailable:')).split()[1])\\n    R.record('verification.json',{'outcome':'TWO_OWNED_CURRENT159_NAMED_LABS_ARCHIVED_STOPPED',\\n        'resources':results,'measuredVmAvailableKB':available,'currentDatabaseTouched':False,\\n        'currentServicesRestarted':False,'fullRestoreRehearsalAccepted':False,'goalUpdated':False})\\n    print('TWO_OWNED_CURRENT159_NAMED_LABS_ARCHIVED_STOPPED',available)\\n\", \".evidence/qyh-current159-named-lab-retention-20261013/material-1.txt\": \"# 历史159完成实验库的保留与内存释放\\n\\nRules：231 原恢复保留、Task/Lease归属及零外部执行门；同一m1写者。先方案后本目录retain.py；不改产品代码、当前库/服务或旧Task归属，不删卷/备份，不启Host。候选A已登记的其他命名卷实验资源归属保留，依赖已完成Task Delivery/无重叠Lease/原证据CID卷及native无clients；候选B原Source权限/锁兼容，仍独立但当前避开大内存执行。选择A。\\n\\n已回读 qyh-current159-fresh-backup-restore-20261012 的完成Delivery FRESH_TRUE159_FULL_NATIVE_RESTORE_DATA_SCHEMA_ACL_SEQUENCES_AND_ROLES_EQUAL。其历史owner为codex-thread-01a107a2-e9e4-7670-bc44-1144fa9b27e2，前缀不同但thread UUID与当前唯一写者一致；以该精确旧owner和Delivery核验，保留旧记录，不改归属。新合法Task接续同维护scope qyh-current159-owned-restore，不凭TTL取锁。\\n\\n精确资源：3fb59cb46c8daeb402caee95bf9f2d9aefbb3aa42d87988811afe29418790687 / qyh-current159-exact-restore-20261012 / aos-qyh-current159-exact-restore-20261012，以及原lab-created.json绑定的 qyh-current159-restore-lab-20261012 / aos-qyh-current159-restore-lab-20261012。当前inspect确认两者均命名卷；第二个旧失败库不当完成库或成功证明，保留其现有状态及数据。\\n\\n复用上一已交付 named-lab 保留脚本中的docker/catalog/record原函数，不复用其硬编码主流程或重复旧stop。每个新子目录中先exact原创建证据CID、native无连接、network-none/noports、命名卷核验；native当前cluster登记为归档身份，不猜历史cluster。全部非模板DB新完整dump和无口令globals、private700/600、第二份同SHA和pg_restore --list，再核目录和clients无变化，才新O_EXCL stop intent及精确CID stop。原volume native存在、所有备份再次同SHA、别的容器不动。已有子阶段intent仅只读对账，不重跑；资源不足或某个归属/连接门拒绝仅限制该资源。\\n\\n完整原卷保留和新备份不代表Host/八台/自然首链或新的完整恢复演练完成。测量剩余内存后再规划有界全库恢复；不会因为停止历史实验实例而重启当前系统。\\n\", \".evidence/qyh-current159-named-lab-retention-20261013/material-2.txt\": \"{\\n  \\\"outcome\\\": \\\"TWO_OWNED_CURRENT159_NAMED_LABS_ARCHIVED_STOPPED\\\",\\n  \\\"resources\\\": [\\n    {\\n      \\\"container\\\": \\\"3fb59cb46c8daeb402caee95bf9f2d9aefbb3aa42d87988811afe29418790687\\\",\\n      \\\"originalVolumeRetained\\\": \\\"aos-qyh-current159-exact-restore-20261012\\\",\\n      \\\"stopped\\\": true,\\n      \\\"completeArchives\\\": 5,\\n      \\\"backupHashesValid\\\": true,\\n      \\\"failedLabPreservedNotAccepted\\\": false\\n    },\\n    {\\n      \\\"container\\\": \\\"951749982fad112b99e59e028c60ec126024c3ea3b1ed6288a2d14cb2d644de2\\\",\\n      \\\"originalVolumeRetained\\\": \\\"aos-qyh-current159-restore-lab-20261012\\\",\\n      \\\"stopped\\\": true,\\n      \\\"completeArchives\\\": 1,\\n     